(function () {
  var p = trg || {};
  // A '@' in a subject breaks consumer delivery and acks; a dotted ref_id
  // misroutes on positional subject parsing. Nothing here reaches a subject,
  // but a record id that carries either is a forged id, not a real one.
  function cleanId(v) {
    var s = String(v == null ? '' : v);
    return /^[A-Za-z0-9_-]{1,128}$/.test(s) ? s : '';
  }
  var quoteId = cleanId(p.quote_id);
  var ver = Number(p.submission_version);
  if (!isFinite(ver)) ver = 0;
  return {
    ok: quoteId !== '' && ver > 0,
    reason: quoteId === '' ? 'missing or malformed quote_id'
          : (ver > 0 ? '' : 'missing or non-positive submission_version'),
    quote_id: quoteId,
    submission_version: ver,
    outcome_filter: JSON.stringify([{ field: 'quote_id', keyword: quoteId }]),
    fields: {
      quote_id: quoteId,
      submission_version: ver,
      quote_reference: String(p.quote_reference || ''),
      outcome: String(p.outcome || ''),
      outcome_status: String(p.outcome_status || ''),
      outcome_current: 'true',
      product_code: String(p.product_code || ''),
      product_version: String(p.product_version || ''),
      decision_seq: Number(p.decision_seq || 0),
      decided_at: String(p.decided_at || ''),
      total_payable: Number(p.total_payable || 0),
      premium_breakdown: (p.premium_breakdown && typeof p.premium_breakdown === 'object') ? p.premium_breakdown : {},
      reasons: Array.isArray(p.reasons) ? p.reasons : [],
      documents: Array.isArray(p.documents) ? p.documents : [],
      quote_validity_expiry: String(p.quote_validity_expiry || ''),
      policy_number: String(p.policy_number || ''),
      bound_at: String(p.bound_at || '')
    }
  };
})();

(function () {
  var rows = (q && q.results) ? q.results : [];
  // The index can return one record twice across an update, so de-duplicate by
  // record id before deciding anything from a count.
  var seen = {}, uniq = [];
  for (var i = 0; i < rows.length; i++) {
    var r = rows[i] || {};
    if (!r.id || seen[r.id]) continue;
    seen[r.id] = true; uniq.push(r);
  }
  if (!nrm.ok) return { action: 'refuse', reason: nrm.reason, record_id: '', stored_version: 0 };
  if (uniq.length === 0) return { action: 'create', reason: 'no outcome record for this quote', record_id: '', stored_version: 0, payload: nrm.fields };
  var cur = uniq[0];
  var stored = Number((cur.data && cur.data.submission_version) || 0);
  if (nrm.submission_version < stored) {
    return { action: 'stale', reason: 'decision for v' + nrm.submission_version + ' arrived after v' + stored, record_id: cur.id, stored_version: stored };
  }
  return { action: 'update', reason: '', record_id: cur.id, stored_version: stored, payload: nrm.fields };
})();
